#!/usr/bin/env python3
"""Reconstruct the frozen standalone v314/v315 sources. Never runs solvers.
Only line edits are encoded; NN weights and test answers are not duplicated.
The generated unified diffs are readable. The parent and outputs are hashed.
"""
from pathlib import Path
import base64,difflib,hashlib,json,zlib
ROOT=Path(__file__).resolve().parents[2]
PARENT="c3f819c2715f397bee0ca95bca12be3196c6f5531dbfeb19358d0afd5f6868ea"
PAYLOAD=""
parent=(ROOT/'src/bin/v311_neural_multistart.cpp').read_bytes()
assert hashlib.sha256(parent).hexdigest()==PARENT, 'parent v311 changed'
text=parent.decode(); original=text.splitlines(True)
for version,record in json.loads(zlib.decompress(base64.b64decode(PAYLOAD))).items():
    lines=original.copy()
    for start,stop,replacement in reversed(record['edits']):
        lines[start:stop]=replacement.splitlines(True)
    result=''.join(lines)
    assert hashlib.sha256(result.encode()).hexdigest()==record['sha256']
    path=ROOT/'src/bin'/f'{version}.cpp'
    if path.exists():assert path.read_bytes()==result.encode(), str(path)+' already differs'
    else:path.write_text(result)
    diff=ROOT/'adhoc'/version[:4]/f'{version}_vs_v311.patch'
    diff.parent.mkdir(parents=True,exist_ok=True)
    diff.write_text(''.join(difflib.unified_diff(original,result.splitlines(True),
        fromfile='a/src/bin/v311_neural_multistart.cpp',tofile=f'b/src/bin/{version}.cpp')))
    print(record['sha256'],path)
